class HitCounter:
    def __init__(self):
        self._count = 0

    def hit(self):
        self._count += 1
        return self._count

def handle(request, counter: HitCounter):   # the dependency is in the signature
    return counter.hit()

# each caller or test creates its own: handle(req, HitCounter())

